-- Comentarios da Lei 15.040/2024, lote 1 (arts. 1 a 20). Autorizados pela Jessica em 22/10/2026; so a partir do texto no banco.
-- Reverter: update legislacao set contexto=null, aplicacao_pratica=null where codigo='lei15040' and numero between 1 and 20 and paragrafo is null and inciso is null;
update legislacao l set contexto=v.c, aplicacao_pratica=v.a from (values
(1,'Conceito de contrato de seguro','Pelo contrato de seguro, a seguradora obriga-se, mediante o pagamento do prêmio equivalente, a garantir interesse legítimo do segurado ou do beneficiário contra riscos predeterminados.'),
(2,'Entidades autorizadas a pactuar seguro','Somente podem pactuar contratos de seguro entidades que se encontrem devidamente autorizadas na forma da lei.'),
(3,'Cessão da posição contratual da seguradora','A seguradora que ceder sua posição contratual a qualquer título, no todo ou em parte, sem concordância prévia dos segurados e de seus beneficiários conhecidos, ou sem autorização prévia e específica da autoridade fiscalizadora, será solidariamente responsável com a seguradora cessionária. O § 1º dispõe que a cessão parcial ou total de carteira por iniciativa da seguradora sempre deverá ser autorizada pela autoridade fiscalizadora. O § 2º dispõe que a cessão de carteira mantém a cedente solidária perante o cedido, caso a cessionária se encontre ou venha a tornar-se insolvente no período de vigência do seguro ou no prazo de 24 (vinte e quatro) meses, contado da cessão da carteira, o que for menor.'),
(4,'Lei aplicável ao contrato de seguro','O contrato de seguro, em suas distintas modalidades, será regido pela Lei. O § 1º dispõe que, sem prejuízo do art. 20 da Lei Complementar n. 126, de 15 de janeiro de 2007, aplica-se exclusivamente a lei brasileira aos contratos de seguro celebrados por seguradora autorizada a operar no Brasil (inciso I), quando o segurado ou o proponente tiver residência ou domicílio no País (inciso II) ou quando os bens sobre os quais recaírem os interesses garantidos se situarem no Brasil (inciso III). O § 2º dispõe que a Lei aplica-se, no que couber, aos seguros regidos por leis próprias.'),
(5,'Interesse legítimo como condição de eficácia','A eficácia do contrato de seguro depende da existência de interesse legítimo. O § 1º dispõe que a superveniência de interesse legítimo torna eficaz o contrato desde então. O § 2º dispõe que, se for parcial o interesse legítimo, a ineficácia não atingirá a parte útil. O § 3º dispõe que, se for impossível a existência do interesse, o contrato será nulo.'),
(6,'Extinção do interesse','Extinto o interesse, resolve-se o contrato com a redução proporcional do prêmio, ressalvado, na mesma proporção, o direito da seguradora às despesas realizadas com a contratação. O parágrafo único dispõe que, se ocorrer redução relevante do interesse, o valor do prêmio será proporcionalmente reduzido, ressalvado, na mesma proporção, o direito da seguradora às despesas realizadas com a contratação.'),
(7,'Devolução do prêmio em contrato nulo ou ineficaz','Quando o contrato de seguro for nulo ou ineficaz, o segurado ou o tomador terá direito à devolução do prêmio, deduzidas as despesas realizadas, salvo se provado que o vício decorreu de sua má-fé.'),
(8,'Seguro sobre a vida e a integridade física de terceiro','No seguro sobre a vida e a integridade física de terceiro, o proponente é obrigado a declarar, sob pena de nulidade do contrato, seu interesse sobre a vida e a incolumidade do segurado. O parágrafo único dispõe que se presume o interesse quando o segurado for cônjuge, companheiro, ascendente ou descendente do terceiro cuja vida ou integridade física seja objeto do seguro celebrado.'),
(9,'Riscos cobertos, exclusões e interpretação favorável ao segurado','O contrato cobre os riscos relativos à espécie de seguro contratada. O § 1º dispõe que os riscos e os interesses excluídos devem ser descritos de forma clara e inequívoca. O § 2º dispõe que, havendo divergência entre a garantia delimitada no contrato e a prevista no modelo de contrato ou nas notas técnicas e atuariais apresentados ao órgão fiscalizador competente, prevalecerá o texto mais favorável ao segurado. O § 3º dispõe que, quando a seguradora se obrigar a garantir diferentes interesses e riscos, o contrato deverá preencher os requisitos exigidos para a garantia de cada um deles, de modo que a nulidade ou a ineficácia de uma garantia não prejudique as demais. O § 4º dispõe que, nos seguros de transporte de bens e de responsabilidade civil pelos danos relacionados a essa atividade, a garantia começa quando as mercadorias são de fato recebidas pelo transportador e cessa com a efetiva entrega ao destinatário. O § 5º dispõe que o contrato não poderá conter cláusula que permita sua extinção unilateral pela seguradora ou que, por qualquer modo, subtraia sua eficácia além das situações previstas em lei.'),
(10,'Classes de risco e garantias nulas','O contrato pode ser celebrado para toda classe de risco, salvo vedação legal. O parágrafo único dispõe que são nulas as garantias, sem prejuízo de outras vedadas em lei, de interesses patrimoniais relativos aos valores das multas e outras penalidades aplicadas em virtude de atos cometidos pessoalmente pelo segurado que caracterizem ilícito criminal (inciso I) e contra risco de ato doloso do segurado, do beneficiário ou de representante de um ou de outro, salvo o dolo do representante do segurado ou do beneficiário em prejuízo desses (inciso II).'),
(11,'Risco impossível ou já realizado','O contrato é nulo quando qualquer das partes souber, no momento de sua conclusão, que o risco é impossível ou já se realizou. O parágrafo único dispõe que a parte que tiver conhecimento da impossibilidade ou da prévia realização do risco e, não obstante, celebrar o contrato pagará à outra o dobro do valor do prêmio.'),
(12,'Desaparecimento do risco','Desaparecido o risco, resolve-se o contrato com a redução do prêmio pelo valor equivalente ao risco a decorrer, ressalvado, na mesma proporção, o direito da seguradora às despesas incorridas com a contratação.'),
(13,'Agravamento intencional do risco','Sob pena de perder a garantia, o segurado não deve agravar intencionalmente e de forma relevante o risco objeto do contrato de seguro. O § 1º dispõe que será relevante o agravamento que conduza ao aumento significativo e continuado da probabilidade de realização do risco descrito no questionário de avaliação de risco referido no art. 44 ou da severidade dos efeitos de tal realização. O § 2º dispõe que, se a seguradora, comunicada nos termos do art. 14, anuir com a continuidade da garantia, cobrando ou não prêmio adicional, será afastada a consequência estabelecida no caput.'),
(14,'Comunicação do agravamento do risco','O segurado deve comunicar à seguradora relevante agravamento do risco tão logo dele tome conhecimento. O § 1º dispõe que, ciente do agravamento, a seguradora poderá, no prazo de 20 (vinte) dias, cobrar a diferença de prêmio ou, se não for tecnicamente possível garantir o novo risco, resolver o contrato, hipótese em que este perderá efeito em 30 (trinta) dias contados do recebimento da notificação de resolução. O § 2º dispõe que a resolução deve ser feita por qualquer meio idôneo que comprove o recebimento da notificação pelo segurado, e a seguradora deverá restituir a eventual diferença de prêmio, ressalvado, na mesma proporção, seu direito ao ressarcimento das despesas incorridas com a contratação. O § 3º dispõe que o segurado que dolosamente descumprir o dever previsto no caput perde a garantia, sem prejuízo da dívida de prêmio e da obrigação de ressarcir as despesas incorridas pela seguradora. O § 4º dispõe que o segurado que culposamente descumprir o dever fica obrigado a pagar a diferença de prêmio apurada ou, se a garantia for tecnicamente impossível ou o fato corresponder a tipo de risco que não seja normalmente subscrito pela seguradora, não fará jus à garantia.'),
(15,'Recusa do segurado ao aumento do prêmio','Se, em consequência do relevante agravamento do risco, o aumento do prêmio for superior a 10% (dez por cento) do valor originalmente pactuado, o segurado poderá recusar a modificação no contrato, resolvendo-o no prazo de 15 (quinze) dias, contado da ciência da alteração no prêmio, com eficácia desde o momento em que o estado de risco foi agravado.'),
(16,'Recusa de indenização e nexo causal com o agravamento','Sobrevindo o sinistro, a seguradora somente poderá recusar-se a indenizar caso prove o nexo causal entre o relevante agravamento do risco e o sinistro caracterizado.'),
(17,'Agravamento do risco nos seguros de vida e integridade física','Nos seguros sobre a vida e a integridade física, mesmo em caso de relevante agravamento do risco, a seguradora somente poderá cobrar a diferença de prêmio.'),
(18,'Redução do risco','Se houver relevante redução do risco, o valor do prêmio será proporcionalmente reduzido, ressalvado, na mesma proporção, o direito da seguradora ao ressarcimento das despesas realizadas com a contratação.'),
(19,'Pagamento do prêmio: tempo, lugar e forma','O prêmio deverá ser pago no tempo, no lugar e na forma convencionados. O § 1º dispõe que, salvo disposição em contrário, o prêmio deverá ser pago à vista e no domicílio do devedor. O § 2º veda o recebimento do prêmio antes de formado o contrato, salvo o caso de cobertura provisória.'),
(20,'Mora no pagamento do prêmio','A mora relativa à prestação única ou à primeira parcela do prêmio resolve de pleno direito o contrato, salvo convenção, uso ou costume em contrário. O § 1º dispõe que a mora relativa às demais parcelas suspenderá a garantia contratual, sem prejuízo do crédito da seguradora ao prêmio, após notificação do segurado concedendo-lhe prazo não inferior a 15 (quinze) dias, contado do recebimento, para a purgação da mora. O § 2º dispõe que a notificação deve ser feita por qualquer meio idôneo que comprove o seu recebimento pelo segurado e conter as advertências de que o não pagamento no novo prazo suspenderá a garantia e de que, não purgada a mora, a seguradora não efetuará pagamento algum relativo a sinistros ocorridos a partir do vencimento original da parcela não paga. O § 3º dispõe que, caso o segurado recuse o recebimento da notificação ou, por qualquer razão, não seja encontrado no último endereço informado à seguradora, o prazo previsto no § 1º terá início na data da frustração da notificação.')
) as v(n,c,a)
where l.codigo='lei15040' and l.numero=v.n and l.paragrafo is null and l.inciso is null and l.vigente;
